40	@Riverpod(keepAlive: true)
41	class CheckpointNotifier extends _$CheckpointNotifier {
42	  int _syncToken = 0;
43	
44	  @override
45	  FutureOr<CheckpointState> build() async {
46	    return _synchronizeLedger();
47	  }
48	
49	  Future<CheckpointState> _synchronizeLedger() async {
50	    final currentToken = ++_syncToken;
51	
52	    try {
53	      final repo = ref.read(checkpointRepositoryProvider);
54	      final result = await repo.fetchCheckpoints();
55	
56	      final checkpoints = result.checkpoints;
57	      final totalCount = result.total == 0 ? checkpoints.length : result.total;
58	
59	      final state = CheckpointState(
60	        checkpoints: checkpoints,
61	        total: totalCount,
62	        isSyncing: result.cursor != null && result.cursor!.isNotEmpty,
63	      );
64	
65	      if (state.isSyncing) {
66	        unawaited(_exhaustCursor(result.cursor!, currentToken));
67	      }
68	
69	      return state;
70	    } on CheckpointError catch (e, st) {
71	      AppLogger.error('Checkpoint provider error', error: e, stackTrace: st);
72	      rethrow;
73	    } catch (e, st) {
74	      AppLogger.error('Checkpoint provider error', error: e, stackTrace: st);
75	      throw const CheckpointSyncError();
76	    }
77	  }
78	
79	  Future<void> _exhaustCursor(String cursor, int token) async {
80	    String? currentCursor = cursor;
81	    final repo = ref.read(checkpointRepositoryProvider);
82	
83	    while (currentCursor != null && currentCursor.isNotEmpty) {
84	      if (token != _syncToken) break;
85	
86	      try {
87	        final result = await repo.fetchCheckpoints(cursor: currentCursor);
88	        final newItems = result.checkpoints;
89	        currentCursor = result.cursor;
90	
91	        final previousState = state.value;
92	        if (previousState != null && token == _syncToken) {
93	          final existingIds =
94	              previousState.checkpoints.map((e) => e.id).toSet();
95	          final uniqueNewItems =
96	              newItems.where((item) => !existingIds.contains(item.id)).toList();
97	
98	          state = AsyncData(
99	            previousState.copyWith(
100	              checkpoints: [...previousState.checkpoints, ...uniqueNewItems],
101	              isSyncing: currentCursor != null && currentCursor.isNotEmpty,
102	            ),
103	          );
104	        }
105	      } catch (e, st) {
106	        AppLogger.error(
107	          'Error fetching checkpoint events',
108	          error: e,
109	          stackTrace: st,
110	        );
111	        break;
112	      }
113	    }
114	  }
115	
116	  Future<void> refresh() async {
117	    state = const AsyncLoading();
118	    state = await AsyncValue.guard(_synchronizeLedger);
119	  }
120	
121	  Future<void> contribute(
122	    String checkpointId,
123	    ContributionStatusEnum status,
124	  ) async {
125	    try {
126	      final repo = ref.read(checkpointRepositoryProvider);
127	      _optimisticUpdate(checkpointId, status);
128	      await repo.contribute(checkpointId, status);
129	    } on CheckpointError {
130	      rethrow;
131	    } catch (e, st) {
132	      AppLogger.error('Checkpoint contribute error', error: e, stackTrace: st);
133	      throw const CheckpointTransmissionError();
134	    }
135	  }
136	
137	  void _optimisticUpdate(String id, ContributionStatusEnum newStatus) {
138	    updateFromRealtime(id, newStatus, DateTime.now().toUtc());
139	  }
140	
141	  void updateFromRealtime(
142	    String id,
143	    ContributionStatusEnum newStatus,
144	    DateTime createdAt,
145	  ) {
146	    final currentState = state.value;
147	    if (currentState == null) return;
148	
149	    final index = currentState.checkpoints.indexWhere((c) => c.id == id);
150	    if (index == -1) return;
151	
152	    final updatedList = List<Checkpoint>.from(currentState.checkpoints);
153	
154	    updatedList[index] = updatedList[index].rebuild((b) {
155	      final newContribution = Contribution(
156	        (c) => c..status = newStatus..createdAt = createdAt,
157	      );
158	
159	      final currentContribs = b.contributions.build().toList();
160	      currentContribs.insert(0, newContribution);
161	
162	      b.contributions = ListBuilder<Contribution>(currentContribs);
163	    });
164	
165	    state = AsyncData(currentState.copyWith(checkpoints: updatedList));
166	  }
167	}
