213	@riverpod
214	AsyncValue<CheckpointState> filteredCheckpoints(Ref ref) {
215	  final query = ref.watch(checkpointSearchProvider).toLowerCase();
216	  final statusFilter = ref.watch(checkpointStatusFilterProvider);
217	  final isNearbyOnly = ref.watch(nearbyOnlyFilterProvider);
218	  final locationAsync = ref.watch(userLocationStreamProvider);
219	  final ledgerAsync = ref.watch(checkpointNotifierProvider);
220	
221	  return ledgerAsync.whenData((data) {
222	    final userPos = locationAsync.value;
223	
224	    bool matchesSearch(Checkpoint c) {
225	      return c.name.toLowerCase().contains(query) ||
226	          '${c.latitude}, ${c.longitude}'.contains(query);
227	    }
228	
229	    bool matchesFilter(Checkpoint c) {
230	      if (statusFilter == null) return true;
231	      final latest =
232	          c.contributions.isNotEmpty ? c.contributions.first.status : null;
233	      return latest == statusFilter;
234	    }
235	
236	    final results =
237	        data.checkpoints.where((c) {
238	          final baseMatch = matchesFilter(c) && matchesSearch(c);
239	          if (isNearbyOnly && userPos != null) {
240	            return baseMatch &&
241	                isWithinProximity(
242	                  c.latitude,
243	                  c.longitude,
244	                  userPos.latitude,
245	                  userPos.longitude,
246	                );
247	          }
248	          return baseMatch;
249	        }).toList();
250	
251	    return data.copyWith(checkpoints: results, total: results.length);
252	  });
253	}
