247	  void _forwardLocation(Position pos) {
248	    final nav = _navigator;
249	    if (nav == null) {
250	      if (_kNavDebug) debugPrint("[NAV] navigator null — skip");
251	      return;
252	    }
253	
254	    // HERE's map-matcher + interpolator REQUIRE a strictly increasing time.
255	    // Geolocator can emit duplicate/regressed timestamps on some Android devices,
256	    // which starves the interpolator and shows up as choppy/laggy marker motion.
257	    var ts = pos.timestamp.toUtc();
258	    final last = _lastLocTime;
259	    if (last != null && !ts.isAfter(last)) {
260	      ts = last.add(const Duration(milliseconds: 1));
261	    }
262	    _lastLocTime = ts;
263	
264	    final location =
265	        Location.withCoordinates(GeoCoordinates(pos.latitude, pos.longitude))
266	          ..time = ts
267	          // Only pass real heading/speed. Geolocator returns 0.0/-1 for "unknown"
268	          // depending on platform; feeding a fake 0° bearing snaps the marker north.
269	          ..bearingInDegrees = pos.heading >= 0 ? pos.heading : null
270	          ..speedInMetersPerSecond = pos.speed >= 0 ? pos.speed : null
271	          ..horizontalAccuracyInMeters = pos.accuracy;
272	
273	    nav.onLocationUpdated(location);
274	
275	    if (_kNavDebug) {
276	      debugPrint(
277	        "[NAV] ${pos.latitude},${pos.longitude} "
278	        "hdg=${location.bearingInDegrees} spd=${location.speedInMetersPerSecond} t=$ts",
279	      );
280	    }
281	  }
