8	const double _kNearbyThresholdMeters = 200;
9	
10	class NearbyCheckpointState {
11	  final Checkpoint checkpoint;
12	  final double distanceMeters;
13	
14	  const NearbyCheckpointState({
15	    required this.checkpoint,
16	    required this.distanceMeters,
17	  });
18	}
19	
20	final nearbyCheckpointProvider =
21	    StateNotifierProvider<NearbyCheckpointNotifier, NearbyCheckpointState?>(
22	  (ref) => NearbyCheckpointNotifier(ref),
23	);
24	
25	class NearbyCheckpointNotifier extends StateNotifier<NearbyCheckpointState?> {
26	  final Ref _ref;
27	  final Set<String> _notifiedIds = {};
28	
29	  NearbyCheckpointNotifier(this._ref) : super(null) {
30	    _ref.listen(userLocationStreamProvider, (previous, next) {
31	      final position = next.value;
32	      if (position != null) _checkProximity(position);
33	    });
34	  }
35	
36	  void _checkProximity(Position position) {
37	    final checkpointState = _ref.read(checkpointNotifierProvider).value;
38	    if (checkpointState == null) return;
39	
40	    final lat = position.latitude;
41	    final lng = position.longitude;
42	
43	    Checkpoint? closest;
44	    double closestDist = double.infinity;
45	
46	    for (final cp in checkpointState.checkpoints) {
47	      if (_notifiedIds.contains(cp.id)) continue;
48	
49	      final dist = _haversineMeters(
50	        lat,
51	        lng,
52	        cp.latitude.toDouble(),
53	        cp.longitude.toDouble(),
54	      );
55	
56	      if (dist <= _kNearbyThresholdMeters && dist < closestDist) {
57	        closest = cp;
58	        closestDist = dist;
59	      }
60	    }
61	
62	    if (closest != null) {
63	      _notifiedIds.add(closest.id);
64	      state = NearbyCheckpointState(
65	        checkpoint: closest,
66	        distanceMeters: closestDist,
67	      );
68	    }
69	  }
70	
71	  void dismiss() {
72	    state = null;
73	  }
74	}
75	
76	double _haversineMeters(
77	  double lat1,
78	  double lng1,
79	  double lat2,
80	  double lng2,
81	) {
82	  const p = 0.017453292519943295;
83	  final a =
84	      0.5 -
85	      cos((lat1 - lat2) * p) / 2 +
86	      cos(lat2 * p) *
87	          cos(lat1 * p) *
88	          (1 - cos((lng1 - lng2) * p)) /
89	          2;
90	  return 12742 * asin(a) * 1000;
91	}
